let shots=[];
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawBG(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#101d23');sky.addColorStop(.65,'#1b2929');sky.addColorStop(1,'#29312b');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant moons and haze
ctx.fillStyle='#d5cc9b';ctx.globalAlpha=.12;ctx.beginPath();ctx.arc(790-camera*.025,110,65,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
for(let layer=0;layer<3;layer++){let factor=.12+layer*.13;let base=layer===0?300:layer===1?348:390;ctx.fillStyle=['#182629','#182326','#1a2523'][layer];for(let i=-1;i<10;i++){let x=i*150-(camera*factor%150),h=90+((i*37+layer*53)%110);rect(x,base-h,90+(i*19%50),h,['#182629','#192629','#1b2928'][layer]);if(layer<2){ctx.fillStyle='#667264';ctx.globalAlpha=.35;for(let wy=base-h+15;wy<base-10;wy+=23)for(let wx=x+12;wx<x+70;wx+=21)if((wx+wy)%3>0)rect(wx,wy,4,7,'#adbd81');ctx.globalAlpha=1;ctx.fillStyle=['#182629','#192629'][layer]}}}
// enormous roots and cables
ctx.strokeStyle='#25332e';ctx.lineWidth=7;for(let i=0;i<8;i++){let x=(i*190-camera*.3)%1100-60;ctx.beginPath();ctx.moveTo(x,0);ctx.bezierCurveTo(x+70,90,x-60,185,x+35,300);ctx.stroke()}
}
function drawWorld(){drawBG();ctx.save();ctx.translate(-camera,0);
// ground
rect(0,ground,worldEnd,90,'#30332a');rect(0,ground,worldEnd,5,'#69715b');for(let x=0;x<worldEnd;x+=65){rect(x+13,ground+25,20,3,'#41483a');rect(x+42,ground+56,13,2,'#242a24')}
// platforms / ruins
platforms.forEach(p=>{rect(p.x,p.y,p.w,p.h,'#4c5445');rect(p.x,p.y,p.w,4,'#a0a17a');rect(p.x+8,p.y+9,p.w-16,3,'#353e36')});
// background towers props
for(let x=110;x<worldEnd;x+=260){rect(x,ground-100,18,100,'#28332e');rect(x-9,ground-106,36,9,'#66705b');rect(x+4,ground-138,3,33,'#69745b');ctx.globalAlpha=.55;rect(x+7,ground-132,5,4,'#e4c985');ctx.globalAlpha=1}
// danger pits markers
for(const x of [870,1260,1960,2490,3130,3610]){rect(x,ground,85,90,'#11191a');for(let j=0;j<4;j++)rect(x+j*24,ground+3,10,4,'#ad6d4e')}
// signposts
[{x:1330,t:'SECTOR 03'},{x:2400,t:'JARDIM DE FERRUGEM'},{x:3860,t:'NÚCLEO CENTRAL'}].forEach(s=>{rect(s.x,ground-64,5,64,'#565d4c');rect(s.x-26,ground-66,58,18,'#39483d');ctx.fillStyle='#d1c791';ctx.font='9px monospace';ctx.fillText(s.t,s.x-22,ground-54)});
// allies
friends.filter(f=>!f.dead).forEach(f=>drawBot(f.x,ground-40,f.color,f.joined?f.name:'',true));
// Mother cell silhouette
if(player.x>3850){ctx.globalAlpha=.8;ctx.fillStyle='#263633';ctx.beginPath();ctx.ellipse(4310,ground-70,115,105,0,Math.PI,0);ctx.fill();for(let i=0;i<7;i++){ctx.strokeStyle='#456357';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(4220+i*25,ground-118);ctx.lineTo(4200+i*30,ground-185-(i%3)*15);ctx.stroke()}ctx.globalAlpha=1;ctx.fillStyle='#b8f28b';ctx.beginPath();ctx.arc(4310,ground-90,7,0,Math.PI*2);ctx.fill();ctx.font='9px monospace';ctx.fillStyle='#b8f28b';ctx.fillText('CÉLULA-MÃE',4260,ground-208)}
// enemies
for(const e of enemies)if(e.alive)drawEnemy(e);
// shots
shots.forEach(s=>{ctx.fillStyle='#b8f28b';ctx.shadowColor='#b8f28b';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(s.x,s.y,5,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});
// player
if(player.invuln<=0||Math.floor(time*15)%2===0)drawBot(player.x,player.y,player.gotColor||'#b8f28b','',false);
if(player.shield>0){ctx.strokeStyle='#b8f28b';ctx.globalAlpha=.55;ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x+13,player.y+20,31,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}if(player.wave>0){ctx.strokeStyle='#e4c985';ctx.globalAlpha=player.wave;ctx.lineWidth=5;ctx.beginPath();ctx.arc(player.x+13,player.y+20,(1-player.wave)*150,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
ctx.restore();}
function drawBot(x,y,color,label,friend){ctx.save();if(friend){ctx.globalAlpha=.5;ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x+13,y+21,27,29,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}rect(x+6,y+12,16,24,'#353f3a');rect(x+2,y+5,23,17,'#4e5e53');rect(x+5,y,17,17,'#667469');rect(x+8,y+7,11,4,color);rect(x+8,y+7,3,3,'#14201d');rect(x+18,y+7,3,3,'#14201d');rect(x+7,y+35,5,7,'#26312c');rect(x+17,y+35,5,7,'#26312c');rect(x+(player.face<0?0:21),y+17,6,5,'#657265');if(label){ctx.font='9px monospace';ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(label,x+14,y-11)}ctx.restore()}
function drawEnemy(e){const bob=Math.sin(time*4+e.phase)*3;rect(e.x+5,e.y+12+bob,28,26,'#573e37');rect(e.x+1,e.y+5+bob,36,19,'#7c5546');rect(e.x+6,e.y+bob,26,17,'#a16750');rect(e.x+9,e.y+7+bob,7,4,'#fa806d');rect(e.x+23,e.y+7+bob,7,4,'#fa806d');rect(e.x+8,e.y+36+bob,7,6,'#352e29');rect(e.x+24,e.y+36+bob,7,6,'#352e29');}
function solidUnder(x,y,w){if(y+42>=ground&&y+42<ground+22)return ground;for(const p of platforms)if(x+w>p.x&&x<p.x+p.w&&y+42<=p.y+8&&y+42>=p.y-8)return p.y;return null}
function hurt(){if(player.invuln>0)return;player.hp--;player.invuln=1.4;player.vy=-6;shake=7;updateHUD();if(player.hp<=0){player.hp=3;player.x=Math.max(50,player.x-180);player.y=360;toast('UNIDADE 09 REINICIADA');updateHUD()}}
function update(dt){time+=dt;if(mode!=='play')return;player.anim+=dt;player.invuln=Math.max(0,player.invuln-dt);player.fire=Math.max(0,player.fire-dt);player.shield=Math.max(0,(player.shield||0)-dt);player.wave=Math.max(0,(player.wave||0)-dt);let speed=keys.a||keys.arrowleft?-1:keys.d||keys.arrowright?1:0;player.vx=speed*190;if(speed)player.face=speed;player.x=Math.max(0,Math.min(worldEnd-player.w,player.x+player.vx*dt));player.vy+=950*dt;let ny=player.y+player.vy*dt;const floor=solidUnder(player.x,ny,player.w);if(floor!==null&&player.vy>=0){player.y=floor-42;player.vy=0;player.grounded=true}else{player.y=ny;player.grounded=false}if(player.y>H+30){hurt();player.y=360;player.vy=0}
if((keys[' ']||keys.w||keys.arrowup)&&player.grounded){player.vy=-410;player.grounded=false;keys[' ']=false;keys.w=false;keys.arrowup=false}
if(player.shield<=0)for(const e of enemies){if(!e.alive)continue;e.x+=e.dir*45*dt;if(e.x<e.lo)e.dir=1;if(e.x>e.hi)e.dir=-1;e.y=ground-42;if(Math.abs(player.x-e.x)<33&&Math.abs(player.y-e.y)<40&&!player.shield)hurt()}
for(const s of shots){s.x+=s.vx;s.life--;for(const e of enemies)if(e.alive&&Math.abs(s.x-e.x-18)<26&&Math.abs(s.y-(ground-20))<35){e.hp--;s.life=0;if(e.hp<=0)e.alive=false}}shots=shots.filter(s=>s.life>0);
// scripted legacies: a companion gives their life to save you at the next threshold
const beats=[{id:'nix',x:1200},{id:'mira',x:2260},{id:'tiko',x:3480}];for(const b of beats){let f=friends.find(a=>a.id===b.id);if(f.joined&&!f.dead&&player.x>b.x){f.joined=false;sacrifice(f);break}}
// gaps: fall in pits naturally
camera=Math.max(0,Math.min(worldEnd-W,player.x-W*.36));if(player.x>4310&&mode==='play')ui.objective.textContent='E · ENFRENTE A VERDADE';else updateHUD();if(shake>0)shake=Math.max(0,shake-25*dt);
}
function loop(stamp){let dt=Math.min(.034,(stamp-last)/1000||.016);last=stamp;update(dt);ctx.save();if(shake)ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);drawWorld();ctx.restore();requestAnimationFrame(loop)}
document.querySelector('#start').addEventListener('click',start);
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup'].includes(k))e.preventDefault();keys[k]=true;if(k==='e'){interact()}if(k==='x'){activate()}if(k==='enter'&&mode==='dialogue'&&!ui.choices.children.length)advance();if(k==='escape'&&mode==='dialogue'&&!ui.choices.children.length)advance()});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});document.querySelectorAll('.mobile-controls button').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();if(k==='e')interact();else if(k==='x')activate();else keys[k]=true});['pointerup','pointercancel','pointerleave'].forEach(type=>b.addEventListener(type,()=>{keys[k]=false}))});
requestAnimationFrame(loop);
})();
</script></body></html>

